function validate(input) {
  const [{ books = [], reading_sessions = [] }] = input;
  const known = new Set(), titles = new Set(), ids = new Set();
  for (const [id, title, author, genre, pages] of books) {
    if ([id, title, author, genre, pages].includes(null)) return 'No value in books may be null.';
    if (known.has(id)) return `book_id ${id} appears twice in books.`;
    known.add(id);
    const folded = String(title).toLowerCase();
    if (titles.has(folded)) return `Two books are titled ${title}.`;
    titles.add(folded);
    if (!(pages >= 1)) return 'pages must be positive.';
  }
  for (const [id, book, reader, pagesRead, rating] of reading_sessions) {
    if ([id, book, reader, pagesRead, rating].includes(null)) return 'No value in reading_sessions may be null.';
    if (ids.has(id)) return `session_id ${id} appears twice in reading_sessions.`;
    ids.add(id);
    if (!known.has(book)) return `book_id ${book} is not in books.`;
    if (!(pagesRead >= 1)) return 'pages_read must be positive.';
    if (!(rating >= 1 && rating <= 5)) return 'session_rating must be between 1 and 5.';
  }
  return null;
}

