function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const adjectives = ['Silent', 'Golden', 'Hidden', 'Broken', 'Distant', 'Crimson', 'Quiet', 'Lost', 'Final', 'Endless', 'Burning', 'Frozen', 'Secret', 'Wild', 'Paper'];
  const nouns = ['River', 'Garden', 'Empire', 'Letter', 'Harbor', 'Mountain', 'Promise', 'Kingdom', 'Voyage', 'Island', 'Mirror', 'Forest', 'Season', 'Signal', 'Orchard'];
  const titles = adjectives.flatMap(a => nouns.map(n => `The ${a} ${n}`));
  for (let i = titles.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [titles[i], titles[j]] = [titles[j], titles[i]]; }
  const authors = ['Harper Lee', 'George Orwell', 'Jane Austen', 'J.D. Salinger', 'F. Scott'];
  const genres = ['Fiction', 'Dystopian', 'Romance', 'Mystery'];
  const readers = ['Alice', 'Bob', 'Carol', 'David', 'Emma', 'Frank', 'Grace', 'Henry'];
  // Each book leans one way: split between love and hate, mostly middling, or mostly liked.
  const moods = [[1, 2, 4, 5], [1, 2, 3, 4, 5], [2, 3, 3, 3, 4], [3, 4, 4, 5, 5], [1, 2, 3, 4, 5, 1, 5]];
  const bookCount = small ? (rand() < 0.1 ? 0 : 1 + Math.floor(rand() * 3)) : 160;
  const books = [];
  for (let i = 0; i < bookCount; i++) books.push([small ? i + 1 : 10 + i, titles[i], pick(authors), pick(genres), 100 + Math.floor(rand() * 500)]);
  const limit = small ? 8 : 2000, sessions = [];
  for (const [id] of books) {
    // At most 40 sessions per book, so rounding the score never decides the 60% threshold.
    const count = Math.min(limit - sessions.length, small ? 3 + Math.floor(rand() * 6) : Math.floor(rand() * 26));
    const mood = pick(moods);
    for (let j = 0; j < count; j++) sessions.push([0, id, pick(readers), 10 + Math.floor(rand() * 140), pick(mood)]);
  }
  const order = sessions.map((_, i) => i + 1);
  for (let i = order.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [order[i], order[j]] = [order[j], order[i]]; }
  sessions.forEach((row, i) => { row[0] = order[i]; });
  return [{ books, reading_sessions: sessions }];
}
